1	// Write side of the notes navigation slice.
2	import { useCallback } from "react";
3	import { useShallow } from "zustand/react/shallow";
4	
5	import * as api from "@/features/notes/api/notes-api";
6	import { useSelection } from "@/app/state/selection-store";
7	import { useEditor } from "@/features/notes/editor/hooks/editor-context";
8	import { useProfiles } from "@/features/profiles/hooks/profiles-context";
9	import {
10	  ARCHIEVE_FOLDER_PATH,
11	  FEED_FOLDER_PATH,
12	  isSystemFolder,
13	} from "@typenotes/shared/constants";
14	import { confirmAction, focusNoScroll } from "@/shared/lib/dom";
15	import { getNoteParentPath } from "@typenotes/shared/notes";
16	import { applyFolderRenameToSelection, collectNotesForFlattening } from "../model/notes-tree-model";
17	import { findNode } from "@/features/notes/navigation/model/tree-ops";
18	import type { FolderNode } from "@typenotes/shared/types";
19	
20	type UseNotesTreeActionsArgs = {
21	  tree: FolderNode | null;
22	  refreshTree: () => Promise<void>;
23	  renamingFolder: string | null;
24	  setRenamingFolder: (path: string | null) => void;
25	  renameValue: string;
26	  setRenameValue: (value: string) => void;
27	};
28	
29	export function useNotesTreeActions({
30	  tree,
31	  refreshTree,
32	  renamingFolder,
33	  setRenamingFolder,
34	  renameValue,
35	  setRenameValue,
36	}: UseNotesTreeActionsArgs) {
37	  const { syncSettings } = useProfiles();
38	  const { clearDraft, clearNote, rightPaneRef } = useEditor();
39	  const {
40	    selectedFolders,
41	    setSelectedFolders,
42	    setLastSelectedFolder,
43	    activeFolder,
44	    setActiveFolder,
45	    setSelectedNotes,
46	    setLastSelectedNote,
47	    activeNote,
48	    setActiveNote,
49	    selectFolder,
50	    selectNote,
51	  } = useSelection(
52	    useShallow((state) => ({
53	      selectedFolders: state.selectedFolders,
54	      setSelectedFolders: state.setSelectedFolders,
55	      setLastSelectedFolder: state.setLastSelectedFolder,
56	      activeFolder: state.activeFolder,
57	      setActiveFolder: state.setActiveFolder,
58	      setSelectedNotes: state.setSelectedNotes,
59	      setLastSelectedNote: state.setLastSelectedNote,
60	      activeNote: state.activeNote,
61	      setActiveNote: state.setActiveNote,
62	      selectFolder: state.selectFolder,
63	      selectNote: state.selectNote,
64	    }))
65	  );
66	
67	  const createNewNote = useCallback(
68	    async (
69	      preferredFolderPath?: string,
70	      initialContent = "",
71	      targetTimestampMs?: number
72	    ) => {
73	      const treeSnapshot = tree ?? (await api.getTree());
74	      const initialFolderPath = preferredFolderPath?.trim() || FEED_FOLDER_PATH;
75	      const targetNode =
76	        findNode(treeSnapshot, initialFolderPath) || findNode(treeSnapshot, FEED_FOLDER_PATH);
77	      if (!targetNode) return null;
78	      const folderPath = targetNode.path;
79	      const created = await api.createNote(
80	        folderPath,
81	        initialContent,
82	        targetTimestampMs,
83	        syncSettings.noteFileNameFormat
84	      );
85	      const path = created.path;
86	      await refreshTree();
87	
88	      // New note creation is a workflow, not just a write: refresh the tree,
89	      // sync selection, and hand focus to the editor in one pass.
90	      selectNote(path, folderPath);
91	      clearDraft();
92	
93	      requestAnimationFrame(() => {
94	        const editorElement =
95	          rightPaneRef.current?.querySelector<HTMLElement>(
96	            ".tiptap-content[contenteditable='true']"
97	          ) || rightPaneRef.current;
98	        focusNoScroll(editorElement);
99	      });
100	
101	      return path;
102	    },
103	    [
104	      clearDraft,
105	      refreshTree,
106	      rightPaneRef,
107	      selectNote,
108	      syncSettings.noteFileNameFormat,
109	      tree,
110	    ]
111	  );
112	
113	  const applyFolderRename = useCallback(
114	    (oldPath: string, newPath: string) => {
115	      const next = applyFolderRenameToSelection(
116	        activeFolder,
117	        selectedFolders,
118	        oldPath,
119	        newPath
120	      );
121	      setActiveFolder(next.activeFolder);
122	      if (next.selectedFolderChanged) {
123	        setSelectedFolders(next.selectedFolders);
124	        setLastSelectedFolder(newPath);
125	      }
126	    },
127	    [activeFolder, selectedFolders, setActiveFolder, setLastSelectedFolder, setSelectedFolders]
128	  );
129	
130	  const startRenameFolder = useCallback(
131	    (path: string) => {
132	      if (isSystemFolder(path)) {
133	        window.alert(`"${path}" is a fixed folder and cannot be renamed.`);
134	        return;
135	      }
136	      const name = path.split("/").pop() || "";
137	      setRenamingFolder(path);
138	      setRenameValue(name);
139	    },
140	    [setRenamingFolder, setRenameValue]
141	  );
142	
143	  const submitRenameFolder = useCallback(async () => {
144	    if (!renamingFolder || !renameValue.trim()) {
145	      setRenamingFolder(null);
146	      return;
147	    }
148	    const oldPath = renamingFolder;
149	    const newPath = await api.renameItem(oldPath, renameValue.trim());
150	    setRenamingFolder(null);
151	    setRenameValue("");
152	    await refreshTree();
153	    applyFolderRename(oldPath, newPath);
154	  }, [applyFolderRename, refreshTree, renamingFolder, renameValue, setRenamingFolder, setRenameValue]);
155	
156	  const cancelRenameFolder = useCallback(() => {
157	    setRenamingFolder(null);
158	    setRenameValue("");
159	  }, [setRenamingFolder, setRenameValue]);
160	
161	  const deleteFolders = useCallback(
162	    async (paths: string[]) => {
163	      if (paths.length === 0) return;
164	      if (paths.some(isSystemFolder)) {
165	        window.alert(`"Feed" and "Archieve" are fixed folders and cannot be deleted.`);
166	        return;
167	      }
168	      const confirmed = await confirmAction(`Delete ${paths.length} folder(s)?`);
169	      if (!confirmed) return;
170	      await api.deleteItems(paths);
171	      setSelectedFolders(new Set());
172	      if (paths.includes(activeFolder)) setActiveFolder("");
173	      await refreshTree();
174	    },
175	    [activeFolder, refreshTree, setActiveFolder, setSelectedFolders]
176	  );
177	
178	  const deleteNotes = useCallback(
179	    async (paths: string[]) => {
180	      if (paths.length === 0) return false;
181	      const confirmed = await confirmAction(`Delete ${paths.length} note(s)?`);
182	      if (!confirmed) return false;
183	      await api.deleteItems(paths);
184	      setSelectedNotes(new Set());
185	      setLastSelectedNote("");
186	      if (paths.includes(activeNote || "")) {
187	        setActiveNote(null);
188	        clearNote();
189	      }
190	      await refreshTree();
191	      return true;
192	    },
193	    [activeNote, clearNote, refreshTree, setActiveNote, setLastSelectedNote, setSelectedNotes]
194	  );
195	
196	  const moveNotesToArchive = useCallback(
197	    async (paths: string[]) => {
198	      if (paths.length === 0) return;
199	      await api.moveItems(paths, ARCHIEVE_FOLDER_PATH);
200	      selectFolder(ARCHIEVE_FOLDER_PATH);
201	      clearNote();
202	      await refreshTree();
203	    },
204	    [clearNote, refreshTree, selectFolder]
205	  );
206	
207	  const moveNotesToFolder = useCallback(
208	    async (paths: string[], destinationPath: string) => {
