1	import { useEffect, useRef, useState } from "react";
2	import { listNotePreviews } from "../../api/notes-api";
3	import {
4	  formatNoteDateLabel,
5	  parseNotePreview,
6	  type NotePreview,
7	} from "@typenotes/shared/format";
8	import { NOTE_PREVIEW_CACHE_PREFIX } from "@/shared/lib/storage";
9	import type { NoteEntry } from "@typenotes/shared/types";
10	
11	type CachedPreview = { updatedMs: number | null; preview: NotePreview };
12	
13	type UseNotePreviewsOptions = {
14	  // Cache reset boundary — changes when the active profile/root changes.
15	  resetKey: string | null;
16	  // localStorage key suffix, or null to disable persistence (encryption on,
17	  // or no profile resolved yet). Plaintext previews must never persist for
18	  // encrypted vaults.
19	  persistKey: string | null;
20	  // Every note path in the vault, used to prune deleted notes from the
21	  // persisted snapshot at write time.
22	  allNotePaths: string[];
23	};
24	
25	const readPersistedPreviews = (persistKey: string): Map<string, CachedPreview> => {
26	  const hydrated = new Map<string, CachedPreview>();
27	  try {
28	    const raw = window.localStorage.getItem(NOTE_PREVIEW_CACHE_PREFIX + persistKey);
29	    if (!raw) {
30	      return hydrated;
31	    }
32	    const parsed = JSON.parse(raw) as Record<string, CachedPreview>;
33	    for (const [path, value] of Object.entries(parsed)) {
34	      if (!value || typeof value !== "object" || !value.preview) {
35	        continue;
36	      }
37	      hydrated.set(path, {
38	        updatedMs: value.updatedMs ?? null,
39	        // Date labels are relative ("yesterday"); recompute for today.
40	        preview: {
41	          ...value.preview,
42	          dateLabel: formatNoteDateLabel(value.preview.updatedMs ?? null),
43	        },
44	      });
45	    }
46	  } catch {
47	    hydrated.clear();
48	  }
49	  return hydrated;
50	};
51	
52	const writePersistedPreviews = (
53	  persistKey: string,
54	  cache: Map<string, CachedPreview>,
55	  livePaths: Set<string>
56	) => {
57	  try {
58	    const storageKey = NOTE_PREVIEW_CACHE_PREFIX + persistKey;
59	    // Merge over the existing snapshot: a refresh scoped to one folder must
60	    // not drop persisted previews of the rest of the vault.
61	    let merged: Record<string, CachedPreview> = {};
62	    try {
63	      const raw = window.localStorage.getItem(storageKey);
64	      if (raw) {
65	        merged = JSON.parse(raw) as Record<string, CachedPreview>;
66	      }
67	    } catch {
68	      merged = {};
69	    }
70	    for (const path of Object.keys(merged)) {
71	      if (!livePaths.has(path)) {
72	        delete merged[path];
73	      }
74	    }
75	    for (const [path, value] of cache) {
76	      if (livePaths.has(path)) {
77	        merged[path] = value;
78	      }
79	    }
80	    window.localStorage.setItem(storageKey, JSON.stringify(merged));
81	  } catch {
82	    // Quota exceeded or storage unavailable — the cache is best-effort.
83	  }
84	};
85	
86	export function useNotePreviews(
87	  notes: NoteEntry[],
88	  { resetKey, persistKey, allNotePaths }: UseNotePreviewsOptions
89	) {
90	  const [notePreviews, setNotePreviews] = useState<Record<string, NotePreview>>({});
91	  const [isLoading, setIsLoading] = useState(false);
92	  const [refreshToken, setRefreshToken] = useState(0);
93	  // Previews accumulate here across refreshes and navigation so revisited
94	  // folders render instantly and unchanged rows keep object identity.
95	  const cacheRef = useRef<Map<string, CachedPreview>>(new Map());
96	  const persistKeyRef = useRef(persistKey);
97	  persistKeyRef.current = persistKey;
98	  const allNotePathsRef = useRef(allNotePaths);
99	  allNotePathsRef.current = allNotePaths;
100	
101	  useEffect(() => {
102	    const onInvalidated = () => {
103	      cacheRef.current.clear();
104	      setRefreshToken((value) => value + 1);
105	    };
106	    window.addEventListener("note-previews-invalidated", onInvalidated);
107	    return () => window.removeEventListener("note-previews-invalidated", onInvalidated);
108	  }, []);
109	
110	  // Profile/root switches replace the cache wholesale with that profile's
111	  // persisted snapshot, so the first paint after launch is instant and stale
112	  // entries from another profile can never leak in.
113	  useEffect(() => {
114	    cacheRef.current = persistKey ? readPersistedPreviews(persistKey) : new Map();
115	    setRefreshToken((value) => value + 1);
116	  }, [persistKey, resetKey]);
117	
118	  useEffect(() => {
119	    if (notes.length === 0) {
120	      setNotePreviews({});
121	      setIsLoading(false);
122	      return;
123	    }
124	    let cancelled = false;
125	    const cache = cacheRef.current;
126	
127	    const run = async () => {
128	      setIsLoading(true);
129	      // Paint whatever is already cached while the fresh batch loads.
130	      const cachedPreviews: Record<string, NotePreview> = {};
131	      notes.forEach((note) => {
132	        const cached = cache.get(note.path);
133	        if (cached) {
