14	import { useGitSyncWorkflows } from "./use-git-sync-workflows";
15	
16	type GitSyncContextValue = {
17	  gitStatus: GitSyncStatus | null;
18	  gitSyncAction: GitSyncAction;
19	  gitSyncError: string | null;
20	  gitSyncBusy: boolean;
21	  gitCommitHistory: GitCommitHistoryEntry[];
22	  gitHistoryBusy: boolean;
23	  gitHistoryError: string | null;
24	  refreshGitStatus: () => Promise<void>;
25	  refreshGitHistory: (limit?: number) => Promise<void>;
26	  connectGitRepo: () => Promise<void>;
27	  gitPull: (opts?: { onAfterPull?: () => Promise<void> }) => Promise<void>;
28	  gitPush: () => Promise<void>;
29	  syncNow: (opts?: {
30	    remote?: string;
31	    branch?: string;
32	    onAfterPull?: () => Promise<void>;
33	  }) => Promise<void>;
34	  setGitStatus: (status: GitSyncStatus | null) => void;
35	  setGitSyncError: (error: string | null) => void;
36	};
37	
38	const GitSyncContext = createContext<GitSyncContextValue | null>(null);
39	
40	export function GitSyncProvider({ children }: { children: ReactNode }) {
41	  const { activeProfileId, syncSettings, updateSyncSettings } = useProfiles();
42	  const [gitStatus, setGitStatus] = useState<GitSyncStatus | null>(null);
43	  const [gitSyncAction, setGitSyncAction] = useState<GitSyncAction>("idle");
44	  const [gitSyncError, setGitSyncError] = useState<string | null>(null);
45	  const [gitCommitHistory, setGitCommitHistory] = useState<GitCommitHistoryEntry[]>([]);
46	  const [gitHistoryBusy, setGitHistoryBusy] = useState(false);
47	  const [gitHistoryError, setGitHistoryError] = useState<string | null>(null);
48	
49	  const {
50	    gitSyncBusy,
51	    refreshGitStatus,
52	    refreshGitHistory,
53	    connectGitRepo,
54	    gitPull,
55	    gitPush,
56	    syncNow,
57	  } = useGitSyncWorkflows({
58	    gitStatus,
59	    gitSyncAction,
60	    setGitStatus,
61	    setGitSyncAction,
62	    setGitSyncError,
63	    setGitCommitHistory,
64	    setGitHistoryBusy,
65	    setGitHistoryError,
66	    syncSettings,
67	    updateSyncSettings,
68	  });
69	
70	  useEffect(() => {
71	    if (!activeProfileId) {
72	      setGitStatus(null);
73	      setGitSyncError(null);
74	      setGitCommitHistory([]);
75	      setGitHistoryError(null);
76	      return;
77	    }
78	    void refreshGitStatus();
79	    void refreshGitHistory();
80	  }, [activeProfileId, refreshGitHistory, refreshGitStatus]);
81	
82	  useEffect(() => {
83	    if (!activeProfileId || !gitStatus?.repo_initialized) {
84	      return;
85	    }
86	    const patch: Partial<typeof syncSettings> = {};
87	    if (!syncSettings.gitRemoteUrl.trim() && gitStatus.remote_url) {
88	      patch.gitRemoteUrl = gitStatus.remote_url;
89	    }
90	    if (!syncSettings.gitBranch.trim() && gitStatus.current_branch) {
91	      patch.gitBranch = gitStatus.current_branch;
92	    }
93	    if (Object.keys(patch).length > 0) {
94	      updateSyncSettings(patch);
95	    }
96	  }, [
97	    activeProfileId,
98	    gitStatus,
99	    syncSettings.gitBranch,
100	    syncSettings.gitRemoteUrl,
101	    updateSyncSettings,
102	  ]);
103	
104	  return (
105	    <GitSyncContext.Provider
106	      value={{
107	        gitStatus,
108	        gitSyncAction,
109	        gitSyncError,
110	        gitSyncBusy,
111	        gitCommitHistory,
112	        gitHistoryBusy,
113	        gitHistoryError,
114	        refreshGitStatus,
115	        refreshGitHistory,
116	        connectGitRepo,
117	        gitPull,
118	        gitPush,
119	        syncNow,
120	        setGitStatus,
121	        setGitSyncError,
122	      }}
123	    >
124	      {children}
125	    </GitSyncContext.Provider>
126	  );
127	}
128	
