1	import {
2	  useCallback,
3	  useRef,
4	  useState,
5	  type MouseEvent as ReactMouseEvent,
6	  type RefObject,
7	} from "react";
8	import { useShallow } from "zustand/react/shallow";
9	
10	import { useSelection } from "@/app/state/selection-store";
11	import { clearDraft, clearNote } from "@/features/notes/editor/state/editor-store";
12	import { useNotesTree } from "@/features/notes/navigation/state/notes-tree-context";
13	import { findNode } from "@/features/notes/navigation/model/tree-ops";
14	import { focusNoScroll } from "@/shared/lib/dom";
15	import { getNoteParentPath } from "@typenotes/shared/notes";
16	import { computeRangeSelection, resolveTargetPaths } from "@/shared/lib/selection";
17	
18	type UseTreeInteractionsArgs = {
19	  /** The folders pane body; focused after a selection change. */
20	  foldersPanelRef: RefObject<HTMLDivElement | null>;
21	};
22	
23	export type DesktopContextMenuState =
24	  | {
25	      kind: "folder";
26	      x: number;
27	      y: number;
28	      path: string;
29	      targetPaths: string[];
30	    }
31	  | {
32	      kind: "note";
33	      x: number;
34	      y: number;
35	      path: string;
36	      parentPath: string;
37	      targetPaths: string[];
38	    };
39	
40	export type TreeInteractions = {
41	  handleFolderClick: (event: ReactMouseEvent, path: string) => void;
42	  handleToggle: (event: ReactMouseEvent, id: string) => void;
43	  handleNoteClick: (
44	    notePath: string,
45	    event: ReactMouseEvent,
46	    parentPath?: string
47	  ) => void;
48	  handleFolderContextMenu: (
49	    event: ReactMouseEvent,
50	    path: string
51	  ) => Promise<void>;
52	  handleNoteContextMenu: (
53	    event: ReactMouseEvent,
54	    path: string,
55	    parentPath?: string
56	  ) => Promise<void>;
57	  desktopContextMenuState: DesktopContextMenuState | null;
58	  openDesktopContextMenu: (state: DesktopContextMenuState) => void;
59	  closeDesktopContextMenu: () => void;
60	};
61	
62	/**
63	 * Folder/note interaction handlers for the tree UI: range-aware click
64	 * selection, expand/collapse toggling, and the right-click menus (rendered
65	 * as the React/shadcn popup menu the desktop shell owns).
66	 */
67	export const useTreeInteractions = ({
68	  foldersPanelRef,
69	}: UseTreeInteractionsArgs): TreeInteractions => {
70	  const {
71	    selectedFolders,
72	    setSelectedFolders,
73	    lastSelectedFolder,
74	    setLastSelectedFolder,
75	    setActiveFolder,
76	    selectedNotes,
77	    setSelectedNotes,
78	    lastSelectedNote,
79	    setLastSelectedNote,
80	    setActiveNote,
81	    selectFolder,
82	    selectNote,
83	  } = useSelection(
84	    useShallow((state) => ({
85	      selectedFolders: state.selectedFolders,
86	      setSelectedFolders: state.setSelectedFolders,
87	      lastSelectedFolder: state.lastSelectedFolder,
88	      setLastSelectedFolder: state.setLastSelectedFolder,
89	      setActiveFolder: state.setActiveFolder,
90	      selectedNotes: state.selectedNotes,
91	      setSelectedNotes: state.setSelectedNotes,
92	      lastSelectedNote: state.lastSelectedNote,
93	      setLastSelectedNote: state.setLastSelectedNote,
94	      setActiveNote: state.setActiveNote,
95	      selectFolder: state.selectFolder,
96	      selectNote: state.selectNote,
97	    }))
98	  );
99	
100	  const { tree, orderedIds, setExpanded, shouldNestNotesInNavigation } =
101	    useNotesTree();
102	
103	  // Latest selection, readable from menu handlers without re-creating them.
104	  const selectedFoldersRef = useRef<Set<string>>(new Set());
105	  const selectedNotesRef = useRef<Set<string>>(new Set());
106	  selectedFoldersRef.current = selectedFolders;
107	  selectedNotesRef.current = selectedNotes;
108	
109	  const [desktopContextMenuState, setDesktopContextMenuState] =
110	    useState<DesktopContextMenuState | null>(null);
111	
112	  const openDesktopContextMenu = useCallback(
113	    (state: DesktopContextMenuState) => {
114	      setDesktopContextMenuState(state);
115	    },
116	    []
117	  );
118	
119	  const closeDesktopContextMenu = useCallback(() => {
120	    setDesktopContextMenuState(null);
121	  }, []);
122	
123	  const handleFolderClick = (event: ReactMouseEvent, path: string) => {
124	    event.stopPropagation();
125	    selectFolder(
126	      path,
127	      computeRangeSelection(event, selectedFolders, orderedIds, lastSelectedFolder, path)
128	    );
129	    clearDraft();
130	    clearNote();
131	    focusNoScroll(foldersPanelRef.current);
132	  };
133	
134	  const handleToggle = (event: ReactMouseEvent, id: string) => {
135	    event.stopPropagation();
136	    setExpanded((prev) => {
137	      const next = new Set(prev);
138	      if (next.has(id)) next.delete(id);
139	      else next.add(id);
140	      return next;
141	    });
142	  };
143	
144	  const handleFolderContextMenu = async (event: ReactMouseEvent, path: string) => {
145	    event.preventDefault();
146	    event.stopPropagation();
147	    // Keeps the existing multi-selection (and its range anchor) when the
148	    // target folder is already part of it.
149	    if (!selectedFolders.has(path)) {
150	      setSelectedFolders(new Set([path]));
151	      setLastSelectedFolder(path);
152	    }
153	    setActiveFolder(path);
154	    setSelectedNotes(new Set());
155	    setLastSelectedNote("");
156	    setActiveNote(null);
157	    clearDraft();
158	    clearNote();
159	    focusNoScroll(foldersPanelRef.current);
160	
161	    setDesktopContextMenuState({
162	      kind: "folder",
163	      x: event.clientX,
164	      y: event.clientY,
165	      path,
166	      targetPaths: selectedFolders.has(path)
167	        ? resolveTargetPaths(selectedFoldersRef.current, path)
168	        : [path],
169	    });
170	  };
171	
172	  const handleNoteClick = (
173	    notePath: string,
174	    event: ReactMouseEvent,
175	    parentPath?: string
176	  ) => {
177	    const noteParentPath = parentPath ?? getNoteParentPath(notePath);
178	    const parentNode = findNode(tree, noteParentPath);
179	    if (!parentNode) return;
180	    const notePaths = parentNode.notes.map((n) => n.path);
181	    selectNote(
182	      notePath,
183	      noteParentPath,
184	      computeRangeSelection(event, selectedNotes, notePaths, lastSelectedNote, notePath)
185	    );
186	    if (parentPath !== undefined || shouldNestNotesInNavigation) {
187	      focusNoScroll(foldersPanelRef.current);
188	    }
189	  };
190	
191	  const handleNoteContextMenu = async (
192	    event: ReactMouseEvent,
193	    path: string,
194	    parentPath?: string
195	  ) => {
196	    event.preventDefault();
197	    event.stopPropagation();
198	    const noteParentPath = parentPath ?? getNoteParentPath(path);
199	    setSelectedFolders(new Set(noteParentPath ? [noteParentPath] : []));
200	    setLastSelectedFolder(noteParentPath);
201	    setActiveFolder(noteParentPath);
202	    // Keeps the existing multi-selection (and its range anchor) when the
