        items,
        preferredIds: [
          lastSelectedNote,
          lastSelectedFolder,
          activeNote,
          isFeed ? activeFeedGroup : activeFolder,
        ],
        expanded,
        hasNestedItems: (id) => {
          const node = isFeed ? feedNodeById.get(id) : flatItemById.get(id);
          return (
            (node?.children.length ?? 0) > 0 ||
            (shouldNestNotesInNavigation && (node?.notes?.length ?? 0) > 0)
          );
        },
        expand: (id) =>
          setExpanded((prev) => {
            const next = new Set(prev);
            next.add(id);
            return next;
          }),
        collapse: (id) =>
          setExpanded((prev) => {
            const next = new Set(prev);
            next.delete(id);
            return next;
          }),
        selectFolder: (id) => {
          if (isFeed) {
            setActiveFeedGroup(id);
            selectFolder(FEED_FOLDER_PATH);
          } else {
            selectFolder(id);
          }
          clearDraft();
          clearNote();
          focusPanel();
          scrollRowIntoView("data-folder", id);
        },
        selectNote: (id, parentId) => {
          if (isFeed) {
            setActiveFeedGroup(parentId);
            selectNote(id, FEED_FOLDER_PATH);
          } else {
            selectNote(id, parentId);
          }
          focusPanel();
          scrollRowIntoView("data-note", id);
        },
      });
    },
    [
      activeFolder,
      activeNote,
      activeFeedGroup,
      activeNavigationTab,
      appMode,
      clearDraft,
      clearNote,
      expanded,
      flatItemById,
      feedNodeById,
      feedVisibleNavigationItems,
      foldersPanelRef,
      lastSelectedFolder,
      lastSelectedNote,
      middlePaneRef,
      rightPaneRef,
      selectFolder,
      selectNote,
      setActiveFeedGroup,
      setExpanded,
      shouldNestNotesInNavigation,
      visibleNavigationItems,
    ]
  );

  return {
    handleNotesKeyDown,
    handleFoldersKeyDown,
    lastLeftPaneFocusRef,
  };
}

