148	            : `Auto queue: scanned ${result.scanned}, queued ${result.queued}.`;
149	        setHandwritingStatusMessage(label);
150	      } catch (error) {
151	        const message = getErrorMessage(error);
152	        setHandwritingStatusMessage(message);
153	      } finally {
154	        queueBusyRef.current = false;
155	        setHandwritingQueueBusy(false);
156	        void refreshHandwritingJobs();
157	      }
158	    },
159	    [getProviderConfig, refreshHandwritingJobs]
160	  );
161	
162	  const importHandwritingFile = useCallback(
163	    async (file: File, preferredFolderPath?: string | null) => {
164	      setHandwritingImportBusy(true);
165	      try {
166	        const bytes = new Uint8Array(await file.arrayBuffer());
167	        const result = await api.saveHandwritingAttachment(
168	          toBase64(bytes),
169	          file.type || undefined,
170	          file.name || undefined,
171	          resolveTargetFolder(preferredFolderPath),
172	          syncSettings.noteFileNameFormat
173	        );
174	        await onHandwritingComplete(result);
175	        setHandwritingStatusMessage(`Saved ${result.note_path}.`);
176	        void refreshHandwritingJobs();
177	        await queueHandwritingOcr("auto");
178	      } catch (error) {
179	        const message = getErrorMessage(error);
180	        setHandwritingStatusMessage(message);
181	        throw error;
182	      } finally {
183	        setHandwritingImportBusy(false);
184	      }
185	    },
186	    [
187	      onHandwritingComplete,
188	      queueHandwritingOcr,
189	      refreshHandwritingJobs,
190	      resolveTargetFolder,
191	      syncSettings.noteFileNameFormat,
192	    ]
193	  );
194	
195	  const autoQueueConfig = getProviderConfig();
196	  const autoQueueHandwriting = useCallback(
197	    () => queueHandwritingOcr("auto"),
198	    [queueHandwritingOcr]
199	  );
200	  useAutoQueueLoop({
201	    enabled: autoQueueConfig.apiKey.length > 0 && autoQueueConfig.model.length > 0,
202	    delayMs: 0,
203	    onTick: autoQueueHandwriting,
204	  });
205	
206	  return (
207	    <HandwritingContext.Provider
208	      value={{
209	        handwritingImportBusy,
210	        handwritingStatusMessage,
211	        handwritingQueueBusy,
212	        handwritingQueue,
213	        handwritingJobs,
214	        handwritingBusy,
215	        handwritingError,
216	        importHandwritingFile,
217	        refreshHandwritingJobs,
218	        queueHandwritingOcr,
219	      }}
220	    >
221	      {children}
222	    </HandwritingContext.Provider>
223	  );
224	}
225	
226	export function useHandwriting() {
227	  const context = useContext(HandwritingContext);
228	  if (!context) {
229	    throw new Error("useHandwriting must be used within a HandwritingProvider");
230	  }
231	  return context;
232	}

