390	pub fn set_active_profile_state(
391	    app: &AppEnv,
392	    profile_id: &str,
393	) -> Result<NotesProfilesFile, String> {
394	    let mut state = ensure_profiles_state(app)?;
395	    let id = profile_id.trim();
396	    if id.is_empty() {
397	        return Err("Profile id is required.".to_string());
398	    }
399	    if find_profile(&state, id).is_none() {
400	        return Err(format!("Profile not found: {}", id));
401	    }
402	    state.active_profile_id = id.to_string();
403	    write_profiles_state(app, &state)?;
404	    Ok(state)
405	}
406	
407	/// Create a new profile with an auto-generated id and notes root directory.
408	pub fn create_profile_state(
409	    app: &AppEnv,
410	    name: &str,
411	    description: Option<&str>,
412	) -> Result<NotesProfilesFile, String> {
413	    let mut state = ensure_profiles_state(app)?;
414	    let profile_name = normalize_profile_name(name);
415	    let base_id = slugify_profile_id(&profile_name);
416	    let existing: HashSet<String> = state
417	        .profiles
418	        .iter()
419	        .map(|profile| profile.id.clone())
420	        .collect();
421	    let mut profile_id = base_id.clone();
422	    let mut suffix = 2usize;
423	    while existing.contains(&profile_id) {
424	        profile_id = format!("{}-{}", base_id, suffix);
425	        suffix += 1;
426	    }
427	
428	    let profile_root = profile_root_for_id(app, &profile_id)?;
429	    if !profile_root.exists() {
430	        fs::create_dir_all(&profile_root).map_err(|err| err.to_string())?;
431	    }
432	
433	    state.profiles.push(NotesProfileEntry {
434	        id: profile_id.clone(),
435	        name: profile_name,
436	        description: normalize_profile_description(description.unwrap_or("")),
437	        notes_root: profile_root.to_string_lossy().to_string(),
438	    });
439	    state.active_profile_id = profile_id;
440	    write_profiles_state(app, &state)?;
441	    Ok(state)
442	}
443	
444	/// Update a profile's name and/or description.
445	pub fn update_profile_state(
446	    app: &AppEnv,
447	    profile_id: &str,
448	    name: Option<&str>,
449	    description: Option<&str>,
450	) -> Result<NotesProfilesFile, String> {
451	    let mut state = ensure_profiles_state(app)?;
452	    let id = profile_id.trim();
453	    if id.is_empty() {
454	        return Err("Profile id is required.".to_string());
455	    }
456	    let Some(index) = state.profiles.iter().position(|profile| profile.id == id) else {
457	        return Err(format!("Profile not found: {}", id));
458	    };
459	    if let Some(next_name) = name {
460	        state.profiles[index].name = normalize_profile_name(next_name);
461	    }
462	    if let Some(next_description) = description {
463	        state.profiles[index].description = normalize_profile_description(next_description);
464	    }
465	    write_profiles_state(app, &state)?;
466	    Ok(state)
467	}
468	
469	/// Delete a profile (at least one must remain). Switches active if needed.
470	pub fn delete_profile_state(
471	    app: &AppEnv,
472	    profile_id: &str,
473	) -> Result<NotesProfilesFile, String> {
474	    let mut state = ensure_profiles_state(app)?;
475	    let id = profile_id.trim();
476	    if id.is_empty() {
477	        return Err("Profile id is required.".to_string());
478	    }
479	    if state.profiles.len() <= 1 {
480	        return Err("At least one profile must remain.".to_string());
481	    }
